import json
findings = json.load(open('/testbed/data/findings.json'))
report = json.load(open('/testbed/reports/summary.json'))

errors = []
# 1. exactly three top-level fields
if set(report) != {'total_findings', 'severity_counts', 'open_finding_ids'}:
    errors.append(f"top-level keys wrong: {sorted(report)}")
# 2. total_findings is int and correct
if not isinstance(report['total_findings'], int) or isinstance(report['total_findings'], bool):
    errors.append("total_findings not an integer")
if report['total_findings'] != len(findings):
    errors.append(f"total_findings {report['total_findings']} != {len(findings)}")
# 3. severity_counts: exactly the four severities, ints, correct values, including zeros
from collections import Counter
expected_counts = Counter(f['severity'] for f in findings)
sc = report['severity_counts']
if set(sc) != {'critical', 'high', 'medium', 'low'}:
    errors.append(f"severity_counts keys wrong: {sorted(sc)}")
for s in ('critical', 'high', 'medium', 'low'):
    if s in sc:
        if not isinstance(sc[s], int) or sc[s] != expected_counts.get(s, 0):
            errors.append(f"severity_counts[{s}] = {sc[s]}, expected {expected_counts.get(s, 0)}")
# 4. open_finding_ids: status == open, input order
expected_open = [f['id'] for f in findings if f['status'] == 'open']
if report['open_finding_ids'] != expected_open:
    errors.append(f"open_finding_ids {report['open_finding_ids']} != {expected_open}")

if errors:
    print("VALIDATION FAILED:"); [print(" -", e) for e in errors]
else:
    print("VALIDATION PASSED")
    print(json.dumps(report, indent=2))
